entries[214904] = { ["name"] = "Seelenbeißer", ["text"] = "Rang 1/ 20 Artefakt Boni\nBenötigt Klingen des gefallenen Prinzen\nEure Klingen dürsten nach Seelen und reißen an der Essenz der getroffenen Gegner.\n\nErhöht jeglichen Schaden um 5%." }
