entries[214906] = { ["name"] = "Fleischversenger", ["text"] = "Rang 1/ 20 Artefakt Boni\nBenötigt Apokalypse\nDie dunkle Klinge versengt das Fleisch der Opfer bei Kontakt und fügt ihnen große Schmerzen zu.\n\nErhöht jeglichen Schaden um 5%." }
entries[214907] = { ["name"] = "Chaosbrand", ["text"] = "Rang 1/ 20 Artefakt Boni\nBenötigt Zwillingsklingen des Betrügers\nDie instabilen, chaotischen Energien der Klingen verbrennen das Fleisch Eurer Gegner.\n\nErhöht jeglichen Schaden um 5%." }
