entries[214909] = { ["name"] = "Seelenschlinger", ["text"] = "Rang 1/ 20 Artefakt Boni\nBenötigt Kriegsklingen der Aldrachi\nDie Macht unzähliger, von den Klingen entzogener Seelen verstärkt jetzt Eure Widerstandskraft.\n\nErhöht die Rüstung um 10%." }
entries[214910] = { ["name"] = "Goldrinns Zorn", ["text"] = "Rang 1/ 20 Artefakt Boni\nBenötigt Sichel von Elune\nEure Beherrschung von Goldrinns Macht nimmt zu und Eure Zauber werden stetig verheerender.\n\nErhöht jeglichen Schaden um 5%." }
entries[214911] = { ["name"] = "Die Fänge der Ersten", ["text"] = "Rang 1/ 20 Artefakt Boni\nBenötigt Fänge von Ashamane\nEure Verbindung mit dem Avatar von Ashamane wird stärker, wodurch Ihr ihre große Macht besser kanalisieren könnt.\n\nErhöht jeglichen Schaden um 5%." }
entries[214912] = { ["name"] = "Verbindung mit Ursoc", ["text"] = "Rang 1/ 20 Artefakt Boni\nBenötigt Ursocs Klauen\nEure Verbindung mit dem mächtigen Avatar von Ursoc wird täglich stärker und macht Euch immer widerstandsfähiger gegenüber den Angriffen Eurer Gegner.\n\nErhöht die Rüstung um 6%." }
entries[214913] = { ["name"] = "G'Hanirs Erblühen", ["text"] = "Rang 1/ 20 Artefakt Boni\nBenötigt G'Hanir, der Mutterbaum\nWie der Wald, so wächst auch G'Hanir stets weiter, selbst in seinem jetzigen Zustand. Eure Zauber erblühen mit immer größerer Effektivität.\n\nErhöht die hervorgerufene Heilung um 5%." }
entries[214914] = { ["name"] = "Geistgebunden", ["text"] = "Rang 1/ 20 Artefakt Boni\nBenötigt Titanenblitz\nHatis Bande mit Euch werden immer stärker und erhöhen seine und Eure Effektivität im Kampf.\n\nErhöht Euren Schaden und den Eurer Begleiter um 5.00%." }
entries[214915] = { ["name"] = "Windflugpfeile", ["text"] = "Rang 1/ 20 Artefakt Boni\nBenötigt Thas'dorah, Erbstück von Haus Windläufer\nDie uralte Magie dieses Bogens gewährt zunehmende Macht über den Wind, sodass die Pfeile Tod bringend durch die Luft schneiden.\n\nErhöht jeglichen Schaden um 5%." }
entries[214916] = { ["name"] = "Stimme der wilden Götter", ["text"] = "Rang 1/ 20 Artefakt Boni\nBenötigt Fangklaue, Speer der wilden Götter\nWilde Götter aller Arten und Namen erachten den Träger des Speeres als ihren Champion. Solange Ihr Fangklaue weiter verwendet, werdet Ihr von mehr und mehr Macht durchdrungen.\n\nErhöht jeglichen Schaden um 5%." }
entries[214917] = { ["name"] = "Macht der Urahnen", ["text"] = "Rang 1/ 20 Artefakt Boni\nBenötigt Aluneth, Großstab der Magna\nAluneths chaotische Natur beugt sich Eurem Willen und verstärkt Eure Zauber weiter.\n\nErhöht Arkanschaden um 5%." }
entries[214918] = { ["name"] = "Verstärkte Zauberklinge", ["text"] = "Rang 1/ 20 Artefakt Boni\nBenötigt Felo'melorn\nFelo'melorn unterstützt Eure Zauber und verstärkt die vernichtenden Effekte noch weiter.\n\nErhöht Feuerschaden um 5%." }
entries[214919] = { ["name"] = "Zaubergeboren", ["text"] = "Rang 1/ 20 Artefakt Boni\nBenötigt Schwarzfrost, Großstab von Alodi\nDie frei durch Schwarzfrost fließende Macht ermöglicht Euch, mehr und mehr des beängstigenden Potenzials zu nutzen.\n\nErhöht Frostschaden um 5%." }
entries[214920] = { ["name"] = "Zähigkeit des Wanderers", ["text"] = "Rang 1/ 20 Artefakt Boni\nBenötigt Fu Zan, Gefährte des Wanderers\nDie Macht von Fu Zan durchdringt Euch vollständig und erhöht Eure Widerstandskraft im Kampf.\n\nErhöht die Rüstung um 17%." }
entries[214921] = { ["name"] = "Nebelwirken", ["text"] = "Rang 1/ 20 Artefakt Boni\nBenötigt Sheilun, Stab der Nebel\nSheiluns zunächst fast überwältigende Macht wird mit der Zeit zu Eurer zweiten Natur, sodass Ihr Eure Kräfte noch besser beherrscht.\n\nErhöht die hervorgerufene Heilung um 5%." }
entries[214922] = { ["name"] = "Windgetragene Schläge", ["text"] = "Rang 1/ 20 Artefakt Boni\nBenötigt Fäuste der Himmel\nDer Wind flüstert Euren Namen und lässt Eure Fäuste nach vorn schnellen. Je mehr Zeit Ihr mit den Fäusten der Himmel verbringt, desto härter werden Eure Schläge.\n\nErhöht jeglichen Schaden um 5%." }
entries[214923] = { ["name"] = "Silberne Berührung", ["text"] = "Rang 1/ 20 Artefakt Boni\nBenötigt Die Silberne Hand\nDurch Eure edlen Beweggründe und Taten geht Ihr eine starke Verbindung mit dem Hammer des mächtigen Wächters Tyr ein, wodurch Eure rechtschaffenen Zauber immer machtvoller werden.\n\nErhöht die hervorgerufene Heilung um 5%." }
entries[214924] = { ["name"] = "Unnachgiebiges Licht", ["text"] = "Rang 1/ 20 Artefakt Boni\nBenötigt Der Wahrheitshüter\nMit wachsender Macht schüttelt der Wahrheitshüter Angriffe mit zunehmender Leichtigkeit ab.\n\nErhöht Rüstung um 10%." }
entries[214925] = { ["name"] = "Verbotene Flamme", ["text"] = "Rang 1/ 20 Artefakt Boni\nBenötigt Zorn des Lichts\nDie instabile Macht des Zorns des Lichts unterwirft sich Euch und verstärkt Eure Zauber.\n\nErhöht jeglichen Schaden sowie Heilung und Absorptionen um 5%." }
entries[214926] = { ["name"] = "Flamme des Glaubens", ["text"] = "Rang 1/ 20 Artefakt Boni\nBenötigt T'uure, Fanal der Naaru\nEure Verbindung mit T'uure ist mit der Zeit noch stärker geworden und hat die Euch verliehene, ohnehin schon bemerkenswerte Kraft noch weiter verstärkt.\n\nErhöht die hervorgerufene Heilung um 5%." }
entries[214927] = { ["name"] = "Dunkles Flüstern", ["text"] = "Rang 1/ 20 Artefakt Boni\nBenötigt Xal'atath, Klinge des Schwarzen Imperiums\nXal'atath flüstert Euch dunkle Worte der Macht ins Ohr und gewährt Euch geheimes Wissen, das Eure Zauber noch stärker macht.\n\nErhöht Schattenschaden um 5%." }
entries[214928] = { ["name"] = "Des Schlächters Präzision", ["text"] = "Rang 1/ 20 Artefakt Boni\nBenötigt Die Königsmörder\nUnzählige Akte des Tötens haben die Tödlichkeit dieser furchterregenden Klingen noch weiter erhöht.\n\nErhöht jeglichen Schaden um 5%." }
entries[214929] = { ["name"] = "Verfluchter Stahl", ["text"] = "Rang 1/ 20 Artefakt Boni\nBenötigt Die Schreckensklingen\nDie verfluchten Klingen erfüllen Euch mit beängstigender Kraft und steigern die Tödlichkeit Eurer Angriffe noch weiter.\n\nErhöht jeglichen Schaden um 5%." }
entries[214930] = { ["name"] = "Legionsklinge", ["text"] = "Rang 1/ 20 Artefakt Boni\nBenötigt Reißzähne des Verschlingers\nJe häufiger Ihr mit den Reißzähnen als Waffe kämpft, desto schneller und präziser scheinen sie zuzuschlagen.\n\nErhöht jeglichen Schaden um 5%." }
entries[214931] = { ["name"] = "Die Kraft des Sturmhüters", ["text"] = "Rang 1/ 20 Artefakt Boni\nBenötigt Die Faust des Ra-den\nJe mehr Ihr Ra-dens Macht beherrscht, desto verheerender werden Eure Zauber.\n\nErhöht jeglichen Schaden um 5%." }
entries[214932] = { ["name"] = "Erderschütternde Schläge", ["text"] = "Rang 1/ 20 Artefakt Boni\nBenötigt Schicksalshammer\nJe besser Ihr den Schicksalshammer beherrscht, desto machtvoller werden Eure Angriffe.\n\nErhöht jeglichen Schaden um 5%." }
entries[214933] = { ["name"] = "Wechsel der Gezeiten", ["text"] = "Rang 1/ 20 Artefakt Boni\nBenötigt Sharas'dal, Szepter der Gezeiten\nIhr beherrscht die immensen Kräfte von Sharas'dal im Laufe der Zeit immer besser.\n\nErhöht die hervorgerufene Heilung um 5%." }
entries[214934] = { ["name"] = "Seelendieb", ["text"] = "Rang 1/ 20 Artefakt Boni\nBenötigt Ulthalesh, Sense der Totenwinde\nUlthalesh folgt Eurem Befehl und brennt tiefe Narben in die Seelen Eurer Opfer.\n\nErhöht sämtlichen Schaden um 5%. [ Gebrechen : Von 'Seelen ernten' unbeeinflusst ]" }
entries[214935] = { ["name"] = "Thal'kiels Machtaura", ["text"] = "Rang 1/ 20 Artefakt Boni\nBenötigt Schädel der Man'ari\nThal'kiel folgt Eurem Willen und verstärkt Eure Macht.\n\nErhöht jeglichen Schaden um 5%." }
entries[214936] = { ["name"] = "Gestohlene Kraft", ["text"] = "Rang 1/ 20 Artefakt Boni\nBenötigt Szepter des Sargeras\nIhr erschließt immer mehr der Macht im Szepter von Sargeras und in den damit verbundenen entfernten Reichen.\n\nErhöht jeglichen Schaden um 5%." }
entries[214937] = { ["name"] = "Unzerstörbarer Stahl", ["text"] = "Rang 1/ 20 Artefakt Boni\nBenötigt Strom'kar der Kriegsbrecher\nJe besser Ihr Strom'kar meistert, desto verheerender fallen seine Angriffe aus.\n\nErhöht jeglichen Schaden um 5%." }
entries[214938] = { ["name"] = "Titanische Kraft", ["text"] = "Rang 1/ 20 Artefakt Boni\nBenötigt Kriegsschwerter der Valarjar\nDer gnadenlose Zorn der Kriegsschwerter wird immer größer, je mehr Ihr sie verwendet.\n\nErhöht jeglichen Schaden um 5%." }
entries[214939] = { ["name"] = "Unzerstörbares Bollwerk", ["text"] = "Rang 1/ 20 Artefakt Boni\nBenötigt Schuppe des Erdwächters\nEine Schuppe Neltharions ist fast unzerstörbar, und die dem uralten Schild verliehene Macht lässt ihn noch viel stärker werden.\n\nErhöht Rüstung um 10%." }
