entries[215119] = { ["name"] = "Blutritual", ["text"] = "100 Meter Reichweite\nSofort\nDer Zaubernde erschafft Kugeln aus Blutmagie und beschleunigt sie auf das Ziel zu. Kontakt mit einer Kugel lässt sie aufbrechen, wodurch alle Gegner innerhalb von 5 Metern Schattenschaden erleiden." }
