entries[215128] = { ["name"] = "Verfluchtes Blut", ["text"] = "Unbegrenzte Reichweite\nSofort\nInfiziert das Blut von Spielercharakteren mit Alptraumenergie, die ihnen 8 Sek. lang alle 2 Sek. 3730 Schattenschaden zufügt. Wenn dieser Effekt endet, detoniert der Spielercharakter und fügt allen Spielercharakteren innerhalb von 11 Metern 17069 Schattenschaden zu." }
entries[215129] = { ["name"] = "Champion: Altruis der Leidende", ["text"] = "Sofort\nAls niemand sonst Illidans Methode kritisierte, die Brennende Legion ungeachtet aller Opfer zu bekämpfen, war da Altruis. Er ist so stark, wie ein Dämonenjäger nur sein kann, und seine Kampfkraft wird nur von seinem scharfen Intellekt und dem Respekt übertrumpft, den er sich mit seinem Einsatz dafür verschafft hat, die Methoden der Illidari zu verändern." }
entries[215131] = { ["name"] = "Schnelligkeitszone", ["text"] = "Sofort 5 sek. Abklingzeit\nBeschwört ein Feld aus arkaner Energie, die das Tempo aller Einheiten im Feld um 50% erhöht." }
