entries[215461] = { ["name"] = "Nekrotisches Toxin", ["text"] = "100 Meter Reichweite\nSofort\nTrilliax lässt wilde Energien aus zufälligen Gegnern hervorbrechen, die 40 Sek. lang alle 0.5 Sek. Verbündeten innerhalb von 7 Metern 6038 Arkanschaden zufügen.\n\nDieser Effekt stört außerdem Schrubber in der Nähe, entzieht ihnen alle 0.5 Sek. 6% Energie und erhöht ihre Bewegungsgeschwindigkeit um 70%. Jeder Schrubber, der ausgesogen wird, verursacht alle 0.5 Sek. 2987 Arkanschaden." }
